SELECT user_id
FROM public.tb_user
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND user_id = #{userId, jdbcType=BIGINT}
FOR UPDATE

mapper.update:
UPDATE public.tb_push_subscription
SET status = 'INACTIVE',
    inactive_at = COALESCE(inactive_at, CURRENT_TIMESTAMP),
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND user_id = #{userId, jdbcType=BIGINT}
  AND subscription_id = #{subscriptionId, jdbcType=BIGINT}
  AND status = 'ACTIVE'

mapper.select:
SELECT COUNT(*)
FROM public.tb_push_subscription
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND user_id = #{userId, jdbcType=BIGINT}
  AND status = 'ACTIVE'
